B.aeL=new A.jV("fleas",B.ve,"Fleas","\u0627\u0644\u0628\u0631\u0627\u063a\u064a\u062b",B.i4,"Small jumping insects that cause itching. They can cause anaemia in young pets and pass on tapeworm.","\u062d\u0634\u0631\u0627\u062a \u0635\u063a\u064a\u0631\u0629 \u0642\u0627\u0641\u0632\u0629 \u062a\u0633\u0628\u0651\u0628 \u0627\u0644\u062d\u0643\u0651\u0629\u060c \u0648\u0642\u062f \u062a\u0633\u0628\u0651\u0628 \u0641\u0642\u0631 \u0627\u0644\u062f\u0645 \u0644\u0644\u062d\u064a\u0648\u0627\u0646\u0627\u062a \u0627\u0644\u0635\u063a\u064a\u0631\u0629\u060c \u0648\u062a\u0646\u0642\u0644 \u0627\u0644\u062f\u0648\u062f\u0629 \u0627\u0644\u0634\u0631\u064a\u0637\u064a\u0629.",B.cv,B.cv,B.aiw)
B.bfx=s(["A tick stuck to the skin, often around the ears, neck or between the toes.","Fever, weakness and loss of appetite.","Pale gums, a bleeding nose, or red or dark urine: go to the vet now."],t.s)
B.b2Y=s(["\u0642\u064f\u0631\u0627\u062f\u0629 \u0645\u0644\u062a\u0635\u0642\u0629 \u0628\u0627\u0644\u062c\u0644\u062f\u060c \u063a\u0627\u0644\u0628\u064b\u0627 \u062d\u0648\u0644 \u0627\u0644\u0623\u0630\u0646\u064a\u0646 \u0623\u0648 \u0627\u0644\u0631\u0642\u0628\u0629 \u0623\u0648 \u0628\u064a\u0646 \u0627\u0644\u0623\u0635\u0627\u0628\u0639.","\u062d\u0645\u0651\u0649 \u0648\u0636\u0639\u0641 \u0648\u0642\u0644\u0629 \u0641\u064a \u0627\u0644\u0623\u0643\u0644.","\u0644\u062b\u0629 \u0634\u0627\u062d\u0628\u0629\u060c \u0623\u0648 \u0646\u0632\u064a\u0641 \u0645\u0646 \u0627\u0644\u0623\u0646\u0641\u060c \u0623\u0648 \u0628\u0648\u0644 \u0623\u062d\u0645\u0631 \u0623\u0648 \u062f\u0627\u0643\u0646: \u062a\u0648\u062c\u0651\u0647 \u0625\u0644\u0649 \u0627\u0644\u0637\u0628\u064a\u0628 \u0627\u0644\u0628\u064a\u0637\u0631\u064a \u0641\u0648\u0631\u064b\u0627."],t.s)
